\"\"\"Minimal standard-library client for OpenAI's Responses API.\"\"\"

import json
import os
from typing import Any, Dict, Optional
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen


API_URL = \"https://api.openai.com/v1/responses\"


class OpenAIAPIError(RuntimeError):
    \"\"\"An API request failed without exposing its response body.\"\"\"

    def __init__(self, message: str, status_code: Optional[int] = None) -> None:
        super().__init__(message)
        self.status_code = status_code


def create_response(
    prompt: str,
    model: str = \"gpt-4.1-mini\",
    api_key: [REDACTED_SECRET] = None,
    timeout: float = 60,
) -> Dict[str, Any]:
    \"\"\"Send a text prompt and return the decoded Responses API object.

    The API key defaults to the "'``OPENAI_API_KEY`` environment variable. The
    request sets ``store`` to false and this module does not save or log prompts.
    """
    if not isinstance(prompt, str):
        raise TypeError("prompt must be a string")

    key = api_key or os.environ.get("OPENAI_API_KEY")
    if not key:
        raise ValueError("Set OPENAI_API_KEY or pass api_key explicitly")

    payload = json.dumps(
        {"model": model, "input": prompt, "store": False}
    ).encode("utf-8")
    request = Request(
        API_URL,
        data=payload,
        headers={
            "Authorization": "Bearer " + key,
            "Content-Type": "application/json",
        },
        method="POST",
    )

    try:
        with urlopen(request, timeout=timeout) as response:
            result = json.loads(response.read().decode("utf-8"))
    except HTTPError as error:
        raise OpenAIAPIError(
            "OpenAI API request failed", status_code=error.code
        ) from None
    except URLError:
        raise OpenAIAPIError("Could not connect to the OpenAI API") from None
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise OpenAIAPIError("OpenAI API returned an invalid JSON response") from None

    if not isinstance(result, dict):
        raise OpenAIAPIError("OpenAI API returned an unexpected response")
    return result


def extract_output_text(response: Dict[str, Any]) -> str:
    """Join text segments from a decoded Responses API response."""
    segments = []
    for item in response.get("output", []):
        if item.get("type") != "message":
            continue
        for content in item.get("content", []):
            if content.get("type") == "output_text":
                text = content.get("text")
                if isinstance(text, str):
                    segments.append(text)
    return "".join(segments)
